typescript.code:
export function mergeByEvents(intervals: number[][]): number[][] {
  const events: Array<[number, number]> = [];
  for (const [start, end] of intervals) { events.push([start, 1], [end, -1]); }
  events.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const out: number[][] = [];
  let active = 0;
  let start = 0;
  for (const [point, delta] of events) {
    if (active === 0) start = point;
    active += delta;
    if (active === 0) out.push([start, point]);
  }
  return out;
}

