List<int[]> mergeByEvents(int[][] intervals) {
  List<int[]> events = new ArrayList<>();
  for (int[] interval : intervals) {
    events.add(new int[] { interval[0], 1 });
    events.add(new int[] { interval[1], -1 });
  }
  events.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : b[1] - a[1]);
  List<int[]> out = new ArrayList<>();
  int active = 0, start = 0;
  for (int[] event : events) {
    if (active == 0) start = event[0];
    active += event[1];
    if (active == 0) out.add(new int[] { start, event[0] });
  }
  return out;
}

